// src/pages/Section3.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import './Userdefined.css';

function Userdefined() {
  return (
    <div>
      <header>
        <div className="logo">
          <h1>SonicGLow<br />Cube</h1>
        </div>
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/resources">Resources</Link></li>
            <li><Link to="/cube">SonicGlow Cube</Link></li>
            <li><Link to="/about">About Us</Link></li>
          </ul>
        </nav>
      </header>

      <main>
        <div className="button-container">
          <Link to="/UserText" className="main-button">Text</Link>
          <Link to="/UserNumber" className="main-button">Number</Link>
          <Link to="/UserPattern" className="main-button">Pattern</Link>
        </div>
      </main>
    </div>
  );
}

export default Section3;
